 * 	 console.log(res1)
 * 	 //-> { initrd: '/initramfs-linux.img',root: 'PARTUUID=someuuidhere' }
 * 	 console.log(res2)
 * 	 //-> { somevar: true, root: 'PARTUUID=someuuidhere' }
 */
function linuxCmdline(cmdline)
{
  return cmdline.trim().split(' ').reduce(reducer, {})
}


