            if (is_admin() && is_w3tc_admin_page()) {
                /**
                 * Only admin can see W3TC notices and errors
                 */
                if (!w3_is_multisite()) {
                    add_action('admin_notices', array(
                        &$this,
                        'admin_notices'
                    ));
                }
                add_action('network_admin_notices', array(
                    &$this,
                    'admin_notices'
                ));
            }
        }
    }

